import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"Introducción a workflows","description":"","frontmatter":{},"headers":[],"relativePath":"cloud/github-actions/01-introduccion-a-workflows.md","filePath":"cloud/github-actions/01-introduccion-a-workflows.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"cloud/github-actions/01-introduccion-a-workflows.md"};function t(r,e,l,c,d,p){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="introduccion-a-workflows" tabindex="-1">Introducción a workflows <a class="header-anchor" href="#introduccion-a-workflows" aria-label="Permalink to &quot;Introducción a workflows&quot;">​</a></h1><p>GitHub Actions ejecuta automatización <strong>dentro del repositorio</strong>: tests, builds, linters, deploys. Un <strong>workflow</strong> es un fichero YAML en <code>.github/workflows/</code> que GitHub descubre solo si está en esa ruta y termina en <code>.yml</code> o <code>.yaml</code>.</p><p>No sustituye a un runner de CI externo: es el CI de GitHub, disparado por eventos del propio repo (<code>push</code>, <code>pull_request</code>, cron, disparo manual, …).</p><p>Documentación oficial: <a href="https://docs.github.com/en/actions/get-started/quickstart" target="_blank" rel="noreferrer">Quickstart</a>, <a href="https://docs.github.com/en/actions/using-workflows/workflow-syntax-for-github-actions" target="_blank" rel="noreferrer">sintaxis</a>.</p><h2 id="piezas-mapa-no-el-detalle" tabindex="-1">Piezas (mapa, no el detalle) <a class="header-anchor" href="#piezas-mapa-no-el-detalle" aria-label="Permalink to &quot;Piezas (mapa, no el detalle)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pieza</th><th>Qué es</th></tr></thead><tbody><tr><td>Evento</td><td>Lo que arranca una ejecución (<code>on:</code>).</td></tr><tr><td>Workflow</td><td>El YAML. Puede tener varios jobs.</td></tr><tr><td>Job</td><td>Unidad que corre en <strong>un</strong> runner (VM efímera). En paralelo por defecto.</td></tr><tr><td>Step</td><td>Un comando (<code>run</code>) o una action (<code>uses</code>).</td></tr><tr><td>Runner</td><td>Máquina: <code>ubuntu-latest</code>, Windows, macOS o self-hosted.</td></tr></tbody></table><p>Jobs, steps y runners se desarrollan en el <a href="./02-jobs-steps-y-runners">siguiente capítulo</a>. Los triggers, en el <a href="./03-eventos-y-triggers">capítulo 3</a>.</p><h2 id="primer-workflow" tabindex="-1">Primer workflow <a class="header-anchor" href="#primer-workflow" aria-label="Permalink to &quot;Primer workflow&quot;">​</a></h2><p>Crea <code>.github/workflows/ci.yml</code> en la rama por defecto:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">CI</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    branches</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pull_request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">jobs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    runs-on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ubuntu-latest</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actions/checkout@v6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">echo &quot;El workflow arranco&quot;</span></span></code></pre></div><p>Tras el push, la pestaña <strong>Actions</strong> del repo muestra la ejecución. <code>runs-on: ubuntu-latest</code> pide un runner alojado por GitHub. <code>actions/checkout</code> clona el repo en esa VM: sin checkout, los <code>run</code> no ven tu código.</p><p>Las versiones de las actions oficiales cambian. Fija una major (<code>@v6</code>) o, en producción, un SHA; el capítulo 2 y el de seguridad cubren el pin.</p><h2 id="cuando-usarlo" tabindex="-1">Cuándo usarlo <a class="header-anchor" href="#cuando-usarlo" aria-label="Permalink to &quot;Cuándo usarlo&quot;">​</a></h2><ul><li>CI en cada PR: lint, tests, build.</li><li>Deploy al fusionar <code>main</code> (este repo publica VitePress así).</li><li>Tareas programadas (backups, informes) con <code>schedule</code>.</li></ul><p>No hace falta un workflow por cada script: agrupa pasos relacionados en jobs con un propósito claro.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Guardar el YAML fuera de <code>.github/workflows/</code> o con extensión que no sea YAML: GitHub no lo ejecuta.</li><li>Olvidar <code>actions/checkout</code> y preguntarse por qué <code>npm test</code> no encuentra <code>package.json</code>.</li><li>Disparar deploys en todos los <code>push</code> de todas las ramas. Restringe <code>branches</code> o deja el deploy en un job con <code>needs</code> + condición (capítulo 2).</li><li>Copiar actions de Marketplace sin mirar permisos ni versión.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Un <code>name:</code> legible: aparece en la UI.</li><li>Empieza por un workflow mínimo y añade jobs; no copies un YAML de 200 líneas el primer día.</li><li>En el YAML de este propio repo (<code>validate.yml</code>, <code>deploy.yml</code>) verás el mismo esquema: evento → job → checkout → comandos.</li><li>Secrets y <code>permissions</code> van en el <a href="./05-secrets-permisos-y-seguridad">capítulo 5</a>. No pongas tokens en el YAML.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Añade un workflow que se ejecute en <code>push</code> a tu rama y liste ficheros con <code>ls</code>.</li><li>Fuerza un fallo (<code>run: exit 1</code>) y observa el estado en Actions.</li><li>Abre el <code>validate.yml</code> de este repositorio y localiza <code>on</code>, <code>jobs</code> y <code>steps</code>.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-jobs-steps-y-runners">Jobs, steps y runners</a>.</p>`,23)])])}const k=a(n,[["render",t]]);export{u as __pageData,k as default};
